// ── Measuring Core Web Vitals with PerformanceObserver ────────
function measureWebVitals() {
  // LCP — Largest Contentful Paint
  new PerformanceObserver((list) => {
    const entries = list.getEntries();
    const lcp = entries[entries.length - 1]; // last = largest
    console.log(`LCP: ${lcp.startTime.toFixed(0)}ms`, lcp.element);
  }).observe({ type: 'largest-contentful-paint', buffered: true });

  // CLS — Cumulative Layout Shift
  let clsScore = 0;
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (!entry.hadRecentInput) { // ignore user-initiated shifts
        clsScore += entry.value;
      }
    }
    console.log(`CLS (running): ${clsScore.toFixed(4)}`);
  }).observe({ type: 'layout-shift', buffered: true });

  // INP — Interaction to Next Paint (Chrome 98+)
  let worstInp = 0;
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (entry.interactionId) {
        worstInp = Math.max(worstInp, entry.duration);
        console.log(`INP candidate: ${entry.duration.toFixed(0)}ms`);
      }
    }
  }).observe({ type: 'event', buffered: true, durationThreshold: 16 });
}

measureWebVitals();

// ── Code splitting with dynamic import ────────────────────────
const loadChartModule = async () => {
  // Bundle is split here — chart.js is only downloaded when called
  const { Chart, renderChart } = await import('./chart.js');
  return renderChart;
};

// Load on user interaction (not on page load)
document.getElementById('show-chart')?.addEventListener('click', async () => {
  const renderChart = await loadChartModule();
  renderChart(document.getElementById('chart-container'));
});

// ── Image performance: lazy, sized, modern formats ─────────────
function createOptimizedImage(src, alt, width, height) {
  const img = document.createElement('img');
  img.src     = src;
  img.alt     = alt;
  img.width   = width;   // prevents CLS — browser knows size before load
  img.height  = height;
  img.loading = 'lazy';  // defer off-screen images
  img.decoding = 'async'; // decode off main thread
  return img;
}

